let raw = String($input.first().json.output || '');

const tryParseJson = (value) => {
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
};

const extractJsonStringField = (text, field) => {
  const match = text.match(new RegExp(`\"${field}\"\\s*:\\s*\"([\\s\\S]*?)\"(?=,\\s*\"|\\s*})`));
  if (!match) return null;

  return match[1]
    .replace(/\\r\\n/g, '\n')
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '\r')
    .replace(/\\t/g, '\t')
    .replace(/\\\"/g, '"')
    .replace(/\\\\/g, '\\');
};

const normalizeCommunicationOutput = (value) => {
  let current = String(value || '').trim();
  if (!current) return current;

  if (current.includes('Communication_Agent_response')) {
    const outer = tryParseJson(current);
    const nested = outer?.Communication_Agent_response?.content;
    if (typeof nested === 'string') {
      current = nested;
    }
  }

  const nestedParsed = tryParseJson(current);
  if (Array.isArray(nestedParsed) && nestedParsed[0]?.output !== undefined) {
    current = String(nestedParsed[0].output || '');
  } else if (nestedParsed && typeof nestedParsed === 'object' && nestedParsed.output !== undefined) {
    current = String(nestedParsed.output || '');
  }

  return current.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
};

const parseEmailPayload = (value) => {
  const parsed = tryParseJson(value);
  if (parsed && typeof parsed === 'object') {
    const bodyHtml = parsed.body_html || parsed.message || '';
    const bodyText = parsed.body_text || '';
    return {
      ...parsed,
      message: bodyHtml || bodyText,
      body_html: bodyHtml,
      body_text: bodyText,
    };
  }

  const action = extractJsonStringField(value, 'action');
  const to = extractJsonStringField(value, 'to');
  const subject = extractJsonStringField(value, 'subject');
  const message = extractJsonStringField(value, 'message');
  const bodyHtml = extractJsonStringField(value, 'body_html');
  const bodyText = extractJsonStringField(value, 'body_text');

  if (!subject && !message && !bodyHtml && !bodyText) {
    throw new Error('Gagal mem-parse payload email dari Communication Agent');
  }

  return {
    action: action || 'send',
    to,
    subject: subject || '(tanpa subjek)',
    message: bodyHtml || message || bodyText || '',
    body_html: bodyHtml || message || '',
    body_text: bodyText || '',
  };
};

raw = normalizeCommunicationOutput(raw);

const output = parseEmailPayload(raw);
const token = $('Main Webhook').first().json.body.google_access_token;

const rawEmail = [
  'To: ' + output.to,
  'Subject: ' + output.subject,
  'MIME-Version: 1.0',
  'Content-Type: text/html; charset=utf-8',
  '',
  output.body_html || output.message || output.body_text || ''
].join('\r\n');

const encoded = Buffer.from(rawEmail)
  .toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/, '');

return [{
  json: {
    raw: encoded,
    to: output.to,
    subject: output.subject,
    body_html: output.body_html || output.message || '',
    body_text: output.body_text || '',
    token: token
  }
}];

const rawOutput = $input.first().json.output;

const unwrapAgentOutput = (value) => {
  let current = value;
  for (let i = 0; i < 3; i += 1) {
    if (Array.isArray(current) && current[0]?.output !== undefined) {
      current = current[0].output;
      continue;
    }

    if (current && typeof current === 'object' && current.output !== undefined) {
      current = current.output;
      continue;
    }

    if (typeof current === 'string') {
      const trimmed = current.trim();
      if ((trimmed.startsWith('[') || trimmed.startsWith('{')) && trimmed.includes('"output"')) {
        try {
          current = JSON.parse(trimmed);
          continue;
        } catch (error) {}
      }
    }

    break;
  }

  return String(current || '');
};

const decodeHtml = (value) => String(value || '')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'")
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>');

const escapeHtml = (value) => String(value || '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const stripTags = (value) => decodeHtml(String(value || '').replace(/<[^>]+>/g, ' '))
  .replace(/\\n/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const normalizeTitle = (value) => String(value || '')
  .replace(/\\n/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const ensureSlideClass = (openTag) => {
  if (/class\s*=\s*["'][^"']*slide[^"']*["']/i.test(openTag)) {
    return openTag.replace(/class\s*=\s*(["'])([^"']*)(\1)/i, (full, quote, classNames) => {
      const merged = Array.from(new Set(classNames.split(/\s+/).filter(Boolean).concat('slide'))).join(' ');
      return `class=${quote}${merged}${quote}`;
    });
  }
  return openTag.replace('<section', '<section class="slide"');
};

const buildFallbackSlide = (content) => {
  const plain = stripTags(content || '') || normalizeTitle($('Main Webhook').first().json.body.message || 'Presentasi');
  const sentences = plain.split(/(?<=[.!?])\s+/).filter(Boolean);
  const title = sentences[0] || plain || 'Presentasi';
  const body = sentences.slice(1).join(' ') || plain;
  return `<section class="slide title-slide"><h1>${escapeHtml(title)}</h1><p>${escapeHtml(body)}</p></section>`;
};

const promoteFirstSubheading = (body, fallbackTitle) => {
  const h2Match = body.match(/<h2\b[^>]*>([\s\S]*?)<\/h2>/i);
  if (h2Match) {
    const h2Full = h2Match[0];
    const h2Inner = h2Match[1];
    return {
      body: body.replace(h2Full, '').trim(),
      title: stripTags(h2Inner) || fallbackTitle,
    };
  }
  return { body, title: fallbackTitle };
};

const raw = unwrapAgentOutput(rawOutput)
  .replace(/```html/gi, '')
  .replace(/```/g, '')
  .replace(/Presentasi Anda sudah siap[\s\S]*$/i, '')
  .replace(/<\/?(?:html|body|main|article)[^>]*>/gi, '')
  .trim();

const sectionRegex = /<section\b[^>]*>[\s\S]*?<\/section>/gi;
const rawSections = raw.match(sectionRegex) || [];
const normalizedSections = rawSections.map((sectionHtml, index) => {
  const openTagMatch = sectionHtml.match(/^<section\b[^>]*>/i);
  const closeTagMatch = sectionHtml.match(/<\/section>\s*$/i);
  const openTag = ensureSlideClass(openTagMatch ? openTagMatch[0] : '<section class="slide">');
  let body = sectionHtml
    .replace(/^<section\b[^>]*>/i, '')
    .replace(/<\/section>\s*$/i, '')
    .trim();

  const h1Matches = [...body.matchAll(/<h1\b[^>]*>([\s\S]*?)<\/h1>/gi)];
  if (h1Matches.length === 0) {
    const fallbackTitle = normalizeTitle($('Main Webhook').first().json.body.message || `Slide ${index + 1}`);
    const promoted = promoteFirstSubheading(body, fallbackTitle);
    body = `<h1>${escapeHtml(promoted.title)}</h1>${promoted.body ? `\n${promoted.body}` : ''}`.trim();
  } else if (h1Matches.length > 1) {
    let seen = false;
    body = body.replace(/<h1\b([^>]*)>([\s\S]*?)<\/h1>/gi, (full, attrs, inner) => {
      if (!seen) {
        seen = true;
        return `<h1${attrs}>${inner}</h1>`;
      }
      return `<h2>${inner}</h2>`;
    });
  }

  const extraClass = index === 0 && !/title-slide/.test(openTag) ? ' title-slide' : '';
  const normalizedOpenTag = extraClass
    ? openTag.replace(/class\s*=\s*(["'])([^"']*)(\1)/i, (full, quote, classNames) => `class=${quote}${classNames}${extraClass}${quote}`)
    : openTag;

  return `${normalizedOpenTag}${body}${closeTagMatch ? closeTagMatch[0] : '</section>'}`;
}).filter(Boolean);

const slideMarkup = normalizedSections.length ? normalizedSections : [buildFallbackSlide(raw)];
const wrappedPages = slideMarkup.map((section) => `<div class="pdf-page">${section}</div>`).join('\n');

const pickTitle = (html) => {
  const h1 = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i)?.[1];
  if (h1) return stripTags(h1);
  const h2 = html.match(/<h2[^>]*>([\s\S]*?)<\/h2>/i)?.[1];
  if (h2) return stripTags(h2);
  return stripTags(html);
};

const titleSource = normalizeTitle(pickTitle(wrappedPages) || $('Main Webhook').first().json.body.message || 'Presentasi');
const compactTitle = titleSource.split(/\s+/).slice(0, 8).join(' ').trim() || 'Presentasi';
const slug = compactTitle.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^A-Za-z0-9]+/g, '-').replace(/^-+|-+$/g, '').replace(/-+/g, '-');
const timestamp = $now.setZone('Asia/Jakarta').toFormat('yyyy-MM-dd_HH-mm');
const nama_file_laporan = `${slug || 'Presentasi'}_${timestamp}.pdf`;

const theme = {
