// This node normalizes supervisor pass-through so downstream routing sees
// the original specialist output instead of a paraphrased wrapper.
// It also recovers mistaken pass-through email-send templates
// into the JSON shape expected by Route Output Type.

const inputJson = $input.first().json;
const supervisorOutput = String(inputJson.output || '');
const getOriginalPrompt = () => {
  try {
    return $('Set - Prompt From User').first().json?.PromptFinal || '';
  } catch (error) {
    return '';
  }
};

const originalPrompt = getOriginalPrompt();

const tryParseJson = (value) => {
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
};

const parseSendTemplate = (text) => {
  if (typeof text !== 'string' || !/KIRIMKAN\s+SEKARANG/i.test(text)) {
    return null;
  }

  const normalized = text.replace(/\r/g, '').trim();
  const match = normalized.match(/KIRIMKAN\s+SEKARANG\s+email\s+lengkap\s+dibawah\s+ini\s+ke\s+alamat:\s*([^\n]+)\n+---\n*SUBJECT:\s*([^\n]+)\n+([\s\S]+?)\n*---\s*$/i);

  if (!match) {
    return null;
  }

  return {
    action: 'send',
    to: match[1].trim(),
    subject: match[2].trim(),
    message: match[3].trim(),
  };
};

const extractStepOutput = (value) => {
  let current = value;
  for (let i = 0; i < 4; i += 1) {
    if (Array.isArray(current) && current[0]?.output !== undefined) {
      current = current[0].output;
      continue;
    }
    if (current && typeof current === 'object' && current.output !== undefined) {
      current = current.output;
      continue;
    }
    if (typeof current === 'string') {
      const trimmed = current.trim();
      if ((trimmed.startsWith('[') || trimmed.startsWith('{')) && trimmed.includes('\"output\"')) {
        const parsed = tryParseJson(trimmed);
        if (parsed !== null) {
          current = parsed;
          continue;
        }
      }
    }
    break;
  }
  return String(current || '');
};

const sanitizeDocumentOutput = (value) => {
  let text = String(value || '').trim();
  if (!text) return '';

  text = text.replace(/^```(?:markdown|md)?\s*/i, '').replace(/\s*```$/, '').trim();

  const hasDocumentSignal = /Unduh\s+(Dokumen|Presentasi)\s+\(PDF\)/i.test(text);
  if (!hasDocumentSignal) return text;

  const firstDocumentStart = text.search(/(^|\n)(#\s+|##\s+|<section\b|<div\b|<!DOCTYPE html|<html\b)/i);
  const hasLeadingNarration = /^(Pengguna meminta|Berdasarkan format|Jika Anda menginginkan format|Berikut adalah|Saya akan memilih|Saya akan membuat|Saya memilih format)/i.test(text);

  if (firstDocumentStart > 0 && hasLeadingNarration) {
    text = text.slice(firstDocumentStart).trim();
  }

  text = text.replace(/\n{2,}(Prepared by\s*:[\s\S]*?)(?=\n+Dokumen Anda sudah siap\. Silakan klik tombol 'Unduh Dokumen \(PDF\)' untuk menyimpannya\.|$)/i, '\n\n');
  text = text.replace(/\n{2,}(Disiapkan oleh\s*:[\s\S]*?)(?=\n+Dokumen Anda sudah siap\. Silakan klik tombol 'Unduh Dokumen \(PDF\)' untuk menyimpannya\.|$)/i, '\n\n');
  text = text.replace(/\n{2,}[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}(?=\n+Dokumen Anda sudah siap\. Silakan klik tombol 'Unduh Dokumen \(PDF\)' untuk menyimpannya\.|$)/i, '\n\n');

  return text.trim();
};

const normalizeEmailOutput = (value) => {
  let current = value;

  for (let i = 0; i < 4; i += 1) {
    if (Array.isArray(current) && current[0]?.output !== undefined) {
      current = current[0].output;
      continue;
    }

    if (current && typeof current === 'object') {
      if (current.Communication_Agent_response?.content) {
        current = current.Communication_Agent_response.content;
        continue;
      }
      if (current.output !== undefined) {
        current = current.output;
        continue;
      }
    }

    if (typeof current === 'string') {
      const trimmed = current.trim().replace(/^\`\`\`(?:json)?\s*/i, '').replace(/\s*\`\`\`$/, '').trim();
      const parsed = tryParseJson(trimmed);
      if (parsed !== null) {
        current = parsed;
        continue;
      }
      current = trimmed;
    }

    break;
  }

  if (typeof current === 'object' && current !== null && !Array.isArray(current)) {
    const action = typeof current.action === 'string' ? current.action.trim().toLowerCase() : '';
    if (action === 'send' || action === 'draft') {
      return JSON.stringify(current);
    }
  }

  if (typeof current === 'string') {
    const trimmed = current.trim();
    const parsed = tryParseJson(trimmed);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      const action = typeof parsed.action === 'string' ? parsed.action.trim().toLowerCase() : '';
      if (action === 'send' || action === 'draft') {
        return JSON.stringify(parsed);
      }
    }
  }

  return null;
};

